/// Create, edit and publish templates
#[derive(Debug, Subcommand)]
pub enum TemplatesCommand {
    #[command(name = "fields", about = "Add, change, remove and reorder a template draft's fields")]
    Fields {
        #[command(subcommand)]
        command: TemplatesFieldsCommand,
    },
    #[command(name = "previews", about = "Fill a template with data and get images of its pages, without a submission")]
    Previews {
        #[command(subcommand)]
        command: TemplatesPreviewsCommand,
    },
    #[command(name = "email-actions", about = "Email a template's submissions' files to people when they're processed")]
    EmailActions {
        #[command(subcommand)]
        command: TemplatesEmailActionsCommand,
    },
    #[command(
        name = "list",
        about = "List templates",
        long_about = "List templates\n\nReturns the templates in your account (their drafts), newest first, one page at a time. Each one is a summary: get a template by its ID for its settings, its PDF in full, its HTML, defaults and published versions."
    )]
    List(ListTemplatesArgs),
    #[command(
        name = "get",
        about = "Get a template",
        long_about = "Get a template\n\nReturns a template: its draft, or one of its published versions."
    )]
    Get(GetTemplateArgs),
    #[command(
        name = "create",
        about = "Create a template",
        long_about = "Create a template\n\nCreates an HTML template, or a PDF or Word template from a file you uploaded with the presigned upload (GET /uploads/presign): pass its `fields.key` as `cache_id`. You can send a link to the file (`document_url`) or the file in base64 (`document_base64`) instead, or send the file with the request with POST /templates/upload. A Word template is made from a Word document (.docx) or an OpenDocument text file (.odt), which DocSpring converts to a Word document. It needs its `output_format`: what each submission makes, a Word document (`docx`), an OpenDocument file (`odt`) or a PDF. A page design (`page_designer`) takes its `layout` in the Page Designer layout format, or starts with an empty page without one.\n\nA PDF template is ready to generate PDFs once DocSpring has processed its PDF, a template created from a `document_url` once its document has been downloaded, and one created from an .odt once it has been converted (`ready` is true). On sync.api hosts the request waits for that unless you pass `wait=false`."
    )]
    Create(CreateTemplateArgs),
    #[command(
        name = "upload",
        about = "Create a template from an uploaded PDF or Word document",
        long_about = "Create a template from an uploaded PDF or Word document\n\nCreates a PDF template from a PDF, or a Word template from a Word document (.docx) or an OpenDocument text file (.odt), sent with the request (`multipart/form-data`). A Word template needs its `output_format`. For large files, upload the file with the presigned upload (GET /uploads/presign) and create the template with POST /templates."
    )]
    Upload(UploadTemplateArgs),
    #[command(
        name = "update",
        about = "Update a template",
        long_about = "Update a template\n\nChanges a template's draft. Properties left out keep their values. `defaults`, `html_engine_options` and a page design's `layout` replace the whole object, and `field_groups` changes only the groups it lists. A new layout adds a field for each new value it reads. Settings such as `webhook_url`, `public_submissions` and `expire_after` apply to every published version too, and setting `parent_folder_id` moves the template and all of its published versions."
    )]
    Update(UpdateTemplateArgs),
    #[command(
        name = "delete",
        about = "Delete a template",
        long_about = "Delete a template\n\nDeletes a template's draft and all of its published versions, or one published version (`version`). Returns the template as it was before it was deleted."
    )]
    Delete(DeleteTemplateArgs),
    #[command(
        name = "copy",
        about = "Copy a template",
        long_about = "Copy a template\n\nCopies a template (its draft, or a published version) into a new template."
    )]
    Copy(CopyTemplateArgs),
    #[command(
        name = "move",
        about = "Move a template to a folder",
        long_about = "Move a template to a folder\n\nMoves a template and all of its published versions to a folder, or to the root (`null`)."
    )]
    Move(MoveTemplateArgs),
    #[command(
        name = "diff",
        about = "Compare a version of a template with the one before it",
        long_about = "Compare a version of a template with the one before it\n\nReturns what changed in the template's draft since its latest published version (or in a published version since the one before it): fields added, removed, changed and moved, the settings that changed, and whether the document was replaced. Check it before you publish a version."
    )]
    Diff(GetTemplateDiffArgs),
    #[command(
        name = "schema",
        about = "Get the JSON Schema of a template's submission data",
        long_about = "Get the JSON Schema of a template's submission data\n\nReturns the JSON Schema that a submission's `data` must match. Use it to check data before you create submissions, or to build a form for the template's fields."
    )]
    Schema(GetTemplateSchemaArgs),
    #[command(
        name = "model-code",
        about = "Generate typed code for a template's submission data",
        long_about = "Generate typed code for a template's submission data\n\nGenerates types for a template's submission data in TypeScript, JavaScript, Ruby, Python, PHP, Java, C#, Elixir, Go or Rust, so your app catches mistakes before it calls the API. `root_type_name` is the type of the whole `data` object, and `just_types=true` leaves out the code that converts JSON to and from the types. Java returns every class in `code`, each under a `// ClassName.java` comment. A template with no named fields returns 422."
    )]
    ModelCode(crate::model_code::ModelCodeArgs),
    #[command(
        name = "page-images",
        about = "Get images of a template's pages",
        long_about = "Get images of a template's pages\n\nReturns a JPEG image of each page of a PDF template's PDF, with temporary links to download them: the draft's PDF, or a published version's. Use them to see the pages that fields are placed on."
    )]
    PageImages(GetTemplatePageImagesArgs),
    #[command(
        name = "publish",
        about = "Publish a template version",
        long_about = "Publish a template version\n\nPublishes the template's draft as a new version. Its content (the PDF or HTML, fields, name and description) never changes, while settings such as `webhook_url` and `public_submissions` keep following the draft. `version_type` says which part of the latest version number goes up. While the template's PDF is downloading or being processed, or DocSpring is setting up its fields, it returns a 409 that says so."
    )]
    Publish(PublishTemplateVersionArgs),
    #[command(
        name = "restore",
        about = "Restore a template version",
        long_about = "Restore a template version\n\nReplaces the template's draft with a copy of one of its published versions. The draft keeps its settings that apply to every version, such as `webhook_url`."
    )]
    Restore(RestoreTemplateVersionArgs),
    #[command(
        name = "update-document",
        about = "Replace a template's document",
        long_about = "Replace a template's document\n\nReplaces a PDF template's PDF, or a Word template's Word document (from a .docx or an .odt), with one you uploaded with the presigned upload (GET /uploads/presign) (`cache_id`), a link to download it from (`document_url`), or the file in base64 (`document_base64`). A PDF template's fields stay where they are, unless `reimport_fields` replaces them with the new PDF's fillable fields, and a Word template gets a field for each new tag. To send the file as `multipart/form-data` instead, use PUT /templates/{template_id}/document/upload."
    )]
    UpdateDocument(UpdateTemplateDocumentArgs),
    #[command(
        name = "upload-document",
        about = "Replace a template's document with an uploaded file",
        long_about = "Replace a template's document with an uploaded file\n\nReplaces a PDF template's PDF, or a Word template's Word document, with one sent with the request (`multipart/form-data`). A PDF template's fields stay where they are, unless `reimport_fields` replaces them with the new PDF's fillable fields, and a Word template gets a field for each new tag."
    )]
    UploadDocument(UploadTemplateDocumentArgs),
    #[command(
        name = "submissions",
        about = "List a template's submissions",
        long_about = "List a template's submissions\n\nReturns a template's submissions (from every version of the template), newest first."
    )]
    Submissions(ListTemplateSubmissionsArgs),
}

