/// Add, change, remove and reorder a template draft's fields
#[derive(Debug, Subcommand)]
pub enum TemplatesFieldsCommand {
    #[command(
        name = "list",
        about = "List a template's fields",
        long_about = "List a template's fields\n\nReturns a template's fields with all of their settings, page by page: the draft's fields, or a published version's. A PDF template's fields are placed on its pages: GET /templates/{template_id}/page_images has images of the pages."
    )]
    List(ListTemplateFieldsArgs),
    #[command(
        name = "add",
        about = "Add fields to a template",
        long_about = "Add fields to a template\n\nAdds fields to a template's draft and returns all of its fields. Publish a version for submissions of published versions to have them. A field with the name of one of the template's fields shares its settings (`type`, `required`, `default`, ...), so a field that sets one to another value is refused: PUT /templates/{template_id}/fields changes them for every field with the name."
    )]
    Add(AddTemplateFieldsArgs),
    #[command(
        name = "update",
        about = "Update a template's fields",
        long_about = "Update a template's fields\n\nChanges fields of a template's draft and returns all of its fields. Settings left out keep their values. A shared setting (`type`, `required`, `default`, ...) changes for every field with the same name."
    )]
    Update(UpdateTemplateFieldsArgs),
    #[command(
        name = "remove",
        about = "Remove fields from a template",
        long_about = "Remove fields from a template\n\nRemoves fields from a template's draft and returns the fields that are left. Conditional logic that used only the removed fields is removed too."
    )]
    Remove(RemoveTemplateFieldsArgs),
    #[command(
        name = "reorder",
        about = "Reorder a template's fields",
        long_about = "Reorder a template's fields\n\nChanges the order of the fields in a template's draft and returns them in their new order. Send every field's ID: each field stays on its page, and a page's fields are printed in this order, so a later field prints over an earlier one where they overlap. Their values are in this order in the template's data schema and forms."
    )]
    Reorder(ReorderTemplateFieldsArgs),
}

impl TemplatesFieldsCommand {
    pub async fn run(self, runner: &Runner) -> CommandResult {
        match self {
            TemplatesFieldsCommand::List(args) => list_template_fields(runner, args).await,
            TemplatesFieldsCommand::Add(args) => add_template_fields(runner, args).await,
            TemplatesFieldsCommand::Update(args) => update_template_fields(runner, args).await,
            TemplatesFieldsCommand::Remove(args) => remove_template_fields(runner, args).await,
            TemplatesFieldsCommand::Reorder(args) => reorder_template_fields(runner, args).await,
        }
    }
}

/// Fill a template with data and get images of its pages, without a submission
#[derive(Debug, Subcommand)]
pub enum TemplatesPreviewsCommand {
    #[command(
        name = "create",
        about = "Preview a template with data",
        long_about = "Preview a template with data\n\nMakes PNG images of a template's pages filled in with the data you send (not a PDF), so you can check how an HTML, PDF or Word template or a page design prints with your data before you publish a version or send live data. A Word template's pages are its PDF's, whatever its `output_format`. It renders the template's draft, or the published `version` you ask for. A preview makes no submission and uses no credits, and its pages are watermarked like a test submission's PDF. It's `pending` while it renders: get it with GET /templates/{template_id}/previews/{preview_id} until it's `processed`, with an image of each page, or `error`."
    )]
    Create(CreateTemplatePreviewArgs),
    #[command(
        name = "get",
        about = "Get a template preview",
        long_about = "Get a template preview\n\nReturns a preview made with POST /templates/{template_id}/previews. Once it's `processed`, `pages` has a PNG image of each page with a temporary link to download it: a preview has no PDF. Previews are deleted an hour after they're created."
    )]
    Get(GetTemplatePreviewArgs),
}

impl TemplatesPreviewsCommand {
    pub async fn run(self, runner: &Runner) -> CommandResult {
        match self {
            TemplatesPreviewsCommand::Create(args) => create_template_preview(runner, args).await,
            TemplatesPreviewsCommand::Get(args) => get_template_preview(runner, args).await,
        }
    }
}

/// Create submissions (filled PDFs and Word documents), and get, list, download and expire them
#[derive(Debug, Subcommand)]
pub enum SubmissionsCommand {
    #[command(name = "batches", about = "Create up to 50 submissions in one request")]
    Batches {
        #[command(subcommand)]
        command: SubmissionsBatchesCommand,
    },
    #[command(
        name = "create",
        about = "Generate a PDF",
        long_about = "Generate a PDF\n\nCreates a submission: fills in a template with your data and generates a PDF. The PDF is generated in the background: on sync.api hosts the request waits for it (unless you pass `wait=false`), otherwise poll GET /submissions/{submission_id} until `state` isn't `pending`.\n\nData that doesn't match the template's fields returns a 422 with an `invalid_data` error. The submission is still saved, with its errors, so you can find it in DocSpring: the error's `submission_id` is its ID.\n\nWith `signature_requests`, the PDF is generated once everyone has signed. DocSpring emails each signer a link to sign, unless `send_email` is false, and can send reminders and the completed document."
    )]
    Create(CreateSubmissionArgs),
    #[command(
        name = "validate",
        about = "Check a submission without creating it",
        long_about = "Check a submission without creating it\n\nChecks a submission as creating it would (its data against the template's fields, its settings and signature requests) without saving it, generating anything or using credits. It doesn't check your account's credits. The response says whether the submission is valid, and if not, has the error that creating it would return."
    )]
    Validate(ValidateSubmissionArgs),
    #[command(
        name = "list",
        about = "List submissions",
        long_about = "List submissions\n\nReturns the submissions in your account, newest first, one page at a time. Each one is a summary: its `data` is null unless you pass `include_data=true`, and its `files` are empty unless you pass `include_files=true`. Get a submission by its ID for its signature requests, uploads and page images."
    )]
    List(ListSubmissionsArgs),
    #[command(
        name = "get",
        about = "Get a submission",
        long_about = "Get a submission\n\nReturns a submission, with its data and links to download its PDF."
    )]
    Get(GetSubmissionArgs),
    #[command(
        name = "expire",
        about = "Expire a submission",
        long_about = "Expire a submission\n\nDeletes a submission's data and PDF now, and returns the expired submission."
    )]
    Expire(ExpireSubmissionArgs),
    #[command(
        name = "generate-files",
        about = "Generate more files",
        long_about = "Generate more files\n\nAdds formats to a processed submission's files, in the background, without using credits again: `pdf`, the PDF of a Word template's submission that made only its Word document (converted from that document), `docx`, the Word document of a Word template's submission that made only its PDF (made again from its data and the template version it used), `odt`, a Word template's submission's OpenDocument file (converted from its Word document, or from one made again when it didn't keep one), and `png`, a PNG image of each page of the PDF (up to 100 pages), which makes the PDF first when the submission doesn't have one. To make them with the submission, add them to `output_formats` when you create it.\n\nEach new file is listed in `files` while it's made: on sync.api hosts the request waits for them (unless you pass `wait=false`), otherwise poll GET /submissions/{submission_id} until none of their `state` is `pending`. A file that couldn't be made has the state `error` and an `error_message`, and the submission stays processed. Asking for a format the submission already has (or is making) changes nothing."
    )]
    GenerateFiles(GenerateSubmissionFilesArgs),
    #[command(
        name = "generate-preview",
        about = "Generate a preview PDF",
        long_about = "Generate a preview PDF\n\nGenerates a preview of a submission's PDF in the background, such as for a submission still waiting for its signature requests. It's in `files.preview` once `preview_generated_at` changes."
    )]
    GeneratePreview(GenerateSubmissionPreviewArgs),
    #[command(name = "download")]
    Download(crate::download::DownloadArgs),
}

impl SubmissionsCommand {
    pub async fn run(self, runner: &Runner) -> CommandResult {
        match self {
            SubmissionsCommand::Batches { command } => command.run(runner).await,
            SubmissionsCommand::Create(args) => create_submission(runner, args).await,
            SubmissionsCommand::Validate(args) => validate_submission(runner, args).await,
            SubmissionsCommand::List(args) => list_submissions(runner, args).await,
            SubmissionsCommand::Get(args) => get_submission(runner, args).await,
            SubmissionsCommand::Expire(args) => expire_submission(runner, args).await,
            SubmissionsCommand::GenerateFiles(args) => generate_submission_files(runner, args).await,
            SubmissionsCommand::GeneratePreview(args) => generate_submission_preview(runner, args).await,
            SubmissionsCommand::Download(args) => crate::download::download(runner, args).await,
        }
    }
}

/// Create up to 50 submissions in one request
#[derive(Debug, Subcommand)]
pub enum SubmissionsBatchesCommand {
    #[command(
        name = "create",
        about = "Generate PDFs in a batch",
        long_about = "Generate PDFs in a batch\n\nCreates up to 50 submissions in one request, from one template or several. The PDFs are only generated when every submission is valid. On sync.api hosts the request waits until every PDF has been generated (unless you pass `wait=false`), otherwise poll GET /submissions/batches/{submission_batch_id} until `processed_at` is set.\n\nWhen any submission is invalid, nothing is generated and the request returns a 422. Submissions whose data doesn't match their template's fields are still saved with their errors (an `invalid_data` error, with each one's `submission_id` in its details), so you can find them in DocSpring. The other submissions aren't saved."
    )]
    Create(CreateSubmissionBatchArgs),
    #[command(
        name = "get",
        about = "Get a batch",
        long_about = "Get a batch\n\nReturns a batch with its submissions. The batch has finished once `processed_at` is set: its `state` is `processed` when every PDF was generated, or `error` when any submission failed."
    )]
    Get(GetSubmissionBatchArgs),
}

impl SubmissionsBatchesCommand {
    pub async fn run(self, runner: &Runner) -> CommandResult {
        match self {
            SubmissionsBatchesCommand::Create(args) => create_submission_batch(runner, args).await,
            SubmissionsBatchesCommand::Get(args) => get_submission_batch(runner, args).await,
        }
    }
}

